from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'fluentx_admin_secure')
path = root / 'lib/features/learn/presentation/screens/learn_hub_screen.dart'
if not path.exists():
    raise SystemExit(f'Learn hub screen not found: {path}')

code = path.read_text()

# Preserve the original LearnHubScreen and all six module definitions. Only add
# a compact personalized roadmap entry above the existing module list.
if "package:supabase_flutter/supabase_flutter.dart" not in code:
    code = code.replace(
        "import 'package:go_router/go_router.dart';\n",
        "import 'package:go_router/go_router.dart';\nimport 'package:supabase_flutter/supabase_flutter.dart' as supabase;\n",
        1,
    )

old = """      body: SafeArea(\n        top: false,\n        child: ListView.separated(\n          padding: const EdgeInsets.all(AppSpacing.base),\n          itemCount: _modules.length,\n          separatorBuilder: (_, __) => const SizedBox(height: AppSpacing.md),\n          itemBuilder: (context, index) {\n            final module = _modules[index];\n            return AppCard(\n              onTap: () => context.push(module.route),\n              child: Row(\n                children: [\n                  Container(\n                    width: 48,\n                    height: 48,\n                    decoration: BoxDecoration(\n                      color: module.color.withValues(alpha: 0.12),\n                      borderRadius: AppRadius.mdAll,\n                    ),\n                    child: Icon(module.icon, color: module.color, size: 22),\n                  ),\n                  const SizedBox(width: AppSpacing.md),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          module.title,\n                          style: Theme.of(context).textTheme.bodyLarge?.copyWith(\n                                fontWeight: FontWeight.w600,\n                              ),\n                        ),\n                        const SizedBox(height: 2),\n                        Text(module.subtitle, style: Theme.of(context).textTheme.bodySmall),\n                      ],\n                    ),\n                  ),\n                  Icon(\n                    Icons.chevron_right,\n                    size: 20,\n                    color: Theme.of(context).colorScheme.onSurfaceVariant,\n                  ),\n                ],\n              ),\n            );\n          },\n        ),\n      ),"""

new = """      body: SafeArea(\n        top: false,\n        child: ListView(\n          padding: const EdgeInsets.all(AppSpacing.base),\n          children: [\n            FutureBuilder<List<dynamic>>(\n              future: Future.wait<dynamic>([\n                supabase.Supabase.instance.client.rpc('get_my_onboarding_state'),\n                supabase.Supabase.instance.client.rpc('get_my_learning_path'),\n              ]),\n              builder: (context, snapshot) {\n                if (!snapshot.hasData) {\n                  return const AppCard(\n                    child: Padding(\n                      padding: EdgeInsets.symmetric(vertical: AppSpacing.md),\n                      child: Center(child: CircularProgressIndicator()),\n                    ),\n                  );\n                }\n                final stateRaw = snapshot.data![0];\n                final pathRaw = snapshot.data![1];\n                final state = stateRaw is Map\n                    ? Map<String, dynamic>.from(stateRaw)\n                    : <String, dynamic>{};\n                final weeks = pathRaw is List ? pathRaw : const <dynamic>[];\n                final currentWeek = int.tryParse((state['current_week'] ?? 1).toString()) ?? 1;\n                final level = (state['current_cefr_level'] ?? 'A1').toString();\n                Map<String, dynamic>? current;\n                for (final item in weeks) {\n                  if (item is Map &&\n                      int.tryParse((item['week_number'] ?? '').toString()) == currentWeek) {\n                    current = Map<String, dynamic>.from(item);\n                    break;\n                  }\n                }\n                final title = (current?['title'] ?? 'Personalized English').toString();\n                return AppCard(\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Row(\n                        children: [\n                          Container(\n                            width: 48,\n                            height: 48,\n                            alignment: Alignment.center,\n                            decoration: BoxDecoration(\n                              color: Theme.of(context).colorScheme.primaryContainer,\n                              borderRadius: AppRadius.mdAll,\n                            ),\n                            child: Text(\n                              level,\n                              style: TextStyle(\n                                color: Theme.of(context).colorScheme.primary,\n                                fontWeight: FontWeight.w800,\n                              ),\n                            ),\n                          ),\n                          const SizedBox(width: AppSpacing.md),\n                          Expanded(\n                            child: Column(\n                              crossAxisAlignment: CrossAxisAlignment.start,\n                              children: [\n                                Text(\n                                  'Your 60-Week Learning Path',\n                                  style: Theme.of(context).textTheme.bodyLarge?.copyWith(\n                                        fontWeight: FontWeight.w700,\n                                      ),\n                                ),\n                                const SizedBox(height: 2),\n                                Text('Week $currentWeek • $title'),\n                              ],\n                            ),\n                          ),\n                        ],\n                      ),\n                      const SizedBox(height: AppSpacing.md),\n                      ClipRRect(\n                        borderRadius: BorderRadius.circular(99),\n                        child: LinearProgressIndicator(\n                          value: (currentWeek / 60.0).clamp(0.0, 1.0).toDouble(),\n                          minHeight: 7,\n                        ),\n                      ),\n                      const SizedBox(height: AppSpacing.sm),\n                      Text(\n                        'A1 → A2 → B1 → B2 → C1',\n                        style: Theme.of(context).textTheme.bodySmall,\n                      ),\n                    ],\n                  ),\n                );\n              },\n            ),\n            const SizedBox(height: AppSpacing.lg),\n            Text(\n              'Explore All Skills',\n              style: Theme.of(context).textTheme.titleLarge?.copyWith(\n                    fontWeight: FontWeight.w700,\n                  ),\n            ),\n            const SizedBox(height: AppSpacing.md),\n            ..._modules.map((module) => Padding(\n                  padding: const EdgeInsets.only(bottom: AppSpacing.md),\n                  child: AppCard(\n                    onTap: () => context.push(module.route),\n                    child: Row(\n                      children: [\n                        Container(\n                          width: 48,\n                          height: 48,\n                          decoration: BoxDecoration(\n                            color: module.color.withValues(alpha: 0.12),\n                            borderRadius: AppRadius.mdAll,\n                          ),\n                          child: Icon(module.icon, color: module.color, size: 22),\n                        ),\n                        const SizedBox(width: AppSpacing.md),\n                        Expanded(\n                          child: Column(\n                            crossAxisAlignment: CrossAxisAlignment.start,\n                            children: [\n                              Text(\n                                module.title,\n                                style: Theme.of(context).textTheme.bodyLarge?.copyWith(\n                                      fontWeight: FontWeight.w600,\n                                    ),\n                              ),\n                              const SizedBox(height: 2),\n                              Text(module.subtitle, style: Theme.of(context).textTheme.bodySmall),\n                            ],\n                          ),\n                        ),\n                        Icon(\n                          Icons.chevron_right,\n                          size: 20,\n                          color: Theme.of(context).colorScheme.onSurfaceVariant,\n                        ),\n                      ],\n                    ),\n                  ),\n                )),\n          ],\n        ),\n      ),"""

if old not in code:
    raise SystemExit('Original LearnHubScreen layout marker not found; refusing unsafe patch')
code = code.replace(old, new, 1)
path.write_text(code)
print('Conservative personalized learning path patch applied successfully.')
